export function createWatcherIterator(eventQueue, setResolver, isClosed, isAborted) {
    let pendingResolve = null;
    function isDone() {
        return isClosed() || isAborted();
    }
    const doneResult = { done: true, value: undefined };
    return {
        next() {
            if (isDone())
                return Promise.resolve(doneResult);
            const event = eventQueue.shift();
            if (event)
                return Promise.resolve({ done: false, value: event });
            if (pendingResolve) {
                return Promise.reject(new TypeError("FileWatcher does not support concurrent next() calls"));
            }
            return new Promise((resolve) => {
                if (isDone()) {
                    resolve(doneResult);
                    return;
                }
                pendingResolve = resolve;
                setResolver((result) => {
                    pendingResolve = null;
                    resolve(result);
                });
            });
        },
        return() {
            setResolver(null);
            pendingResolve?.(doneResult);
            pendingResolve = null;
            return Promise.resolve(doneResult);
        },
    };
}
export function enqueueWatchEvent(event, eventQueue, getResolver, setResolver) {
    const resolver = getResolver();
    if (!resolver) {
        eventQueue.push(event);
        return;
    }
    setResolver(null);
    resolver({ done: false, value: event });
}
export function createFileWatcher(iterator, cleanup) {
    let closed = false;
    const cleanupOnce = () => {
        if (closed)
            return;
        closed = true;
        cleanup();
    };
    const wrappedIterator = {
        next: () => iterator.next(),
        async return(value) {
            cleanupOnce();
            if (iterator.return)
                return await iterator.return(value);
            return { done: true, value: undefined };
        },
        async throw(error) {
            cleanupOnce();
            if (iterator.throw)
                return await iterator.throw(error);
            throw error;
        },
    };
    return {
        [Symbol.asyncIterator]() {
            return wrappedIterator;
        },
        close: cleanupOnce,
    };
}
